                assert any(c_.get("ls") == "-." for c_ in t_f.F.curves), "excitation curve missing"
                assert "excitation spectrum (green; λ<sub>em</sub> = 520 nm)" in t_f.si_caption("X")
                row_, head_, kind_, phi_ = t_f.tau.props()
