            assert m_.any() and not m_[y0_:y0_ + int(0.1 * W_), x0_:x0_ + int(0.2 * W_)].any(), (fx_, fy_)
            nd_ = t_n.export_dialog(out / "nmr" / "nmr_test.docx")
