            rep_cm = "<sup>13</sup>C NMR (126 MHz, CDCl<sub>3</sub>) &delta; 160.1 (d, <i>J</i> = 245.0 Hz), 21.0 (s)."
            rep_2d = "<sup>1</sup>H NMR (501 MHz, CDCl<sub>3</sub>) &delta; 7.30, 2.10."       # 2D-Bericht: nie eine Zeile
