            assert tb_.isColumnHidden(2) and not tb_.isColumnHidden(1) and t_ir.kpis()[0][1] == "≤ 0.4 %", t_ir.kpis()
            w.irms_state.update(ea_found={}, ea_reason="not obtained (air-sensitive); purity by 1H NMR")
            t_ir.update_ea()
