        with section:
            # Verbindung geaendert (Dialog, Zeichnung): jeder gebaute Tab zeigt sofort die neuen Angaben
            import time as _time_c
            from rdkit import Chem as _ChemC
            from rdkit.Chem import AllChem as _AllChemC
            from elucida.app import demo as DEMOC_
            wc_ = MainWindow()
            wc_.resize(1200, 800)
            wc_.show()
            dc_ = DEMOC_.open_demo(wc_, out / "compound_demo")
            pump(0.6)

            def mol_c_(path, smiles):
                m_ = _ChemC.MolFromSmiles(smiles)
                _AllChemC.Compute2DCoords(m_)
                Path(path).parent.mkdir(parents=True, exist_ok=True)
                Path(path).write_text(DEMOC_.mol_cdxml(m_), encoding="utf-8")
                return str(path)

            def settle_c_(formula):                              # Strukturen laden im Hintergrund
                t_end_c = _time_c.monotonic() + 60
                while _time_c.monotonic() < t_end_c and \
                        (wc_.series[gf_].get("structure_asset") or {}).get("formula") != formula:
                    pump(0.1)
                pump(0.6)
                for k_ in wc_._TAB_BUILD_ORDER:                  # verborgene Tabs zeichnen wie beim Anzeigen
                    if wc_._built(k_):
                        getattr(getattr(wc_, wc_._tab_spec(k_)[0]), "ensure_rendered", lambda: None)()

            # eine Serie mit eigener Struktur und Molmasse, eine mit den Werten der Verbindung (das Beispiel selbst hat
            # nur die Reihe seiner Verbindung: zwei Reihen mit fremder Zeichnung dazuladen)
            csv_c_, cdx_c_, _ = make_selftest_inputs(out / "input_compound")
            wc_.open_csv(csv_c_, ask=False)
            wc_.set_structure(str(cdx_c_), "TEST-A", sync=True)
            go_ = next(g_ for g_, s_ in wc_.series.items() if s_.get("structure"))
            gf_ = next(g_ for g_, s_ in wc_.series.items() if not s_.get("structure"))
            own_c_ = (wc_.series[go_]["mw"], wc_.series[go_]["structure"])
            assert wc_.series[gf_]["mw"] == wc_.compound["mw"] != own_c_[0], (wc_.series, wc_.compound)
            wc_.cmb_series.setCurrentText(gf_)
            pump(0.3)
            settle_c_(None)
            old_c_ = wc_.compound["name"]
            assert all(f"<b>{old_c_}</b>" in t_.lbl_cap.text() for t_ in (wc_.cv_tab, wc_.sec_tab, wc_.nmr_tab))
            epr_cap_c_ = wc_.epr_tab.lbl_cap.text()
            assert wc_.epr_state["cap_species"].startswith(old_c_) and old_c_ in epr_cap_c_, epr_cap_c_
            # 1. wie OK im Dialog: Name, Formel, Molmasse, Struktur
            msgs_c_ = []
            wc_.statusBar().messageChanged.connect(msgs_c_.append)
            wc_.set_compound({**wc_.compound, "name": "Q7", "formula": "C6H6O", "mw": 94.11,
                              "structure": mol_c_(out / "input" / "compound_q7.cdxml", "Oc1ccccc1")})
            settle_c_("C6H6O")
            sp_c_ = wc_.compound["structure"]
            assert "Q7" in wc_.windowTitle() and wc_.nav_buttons[0].full_text == "Q7 · C₆H₆O"   # Tab „Verbindung“
            assert wc_.series[gf_]["mw"] == 94.11 and wc_.ed_mw.text() == "94.11", (wc_.series[gf_]["mw"], wc_.ed_mw.text())
            assert wc_.series[gf_]["structure"] == sp_c_ and wc_.lbl_struct.text() == Path(sp_c_).name
            assert (wc_.series[go_]["mw"], wc_.series[go_]["structure"]) == (94.11, sp_c_) != own_c_   # folgt immer (Nutzerwunsch)
            assert any(go_ in m_ and "94.11" in m_ for m_ in msgs_c_), msgs_c_                      # ersetzte Molmasse wird gemeldet
            assert wc_.fl_state["structure"] == sp_c_ and wc_.fl_tab.lbl_struct.text() == Path(sp_c_).name
            assert wc_.hrms_tab.formula() == ("C6H6O", "project") and "C₆H₆O" in wc_.irms_tab.lbl_ea_formula.text()
            assert wc_.syn_tab.compound_name() == "Q7" and "Q7" in wc_.syn_tab.txt_prev.toPlainText()
            for t_ in (wc_.cv_tab, wc_.sec_tab, wc_.nmr_tab):
                assert "<b>Q7</b>" in t_.lbl_cap.text() and old_c_ not in t_.lbl_cap.text(), t_.lbl_cap.text()
            assert wc_.epr_tab.lbl_cap.text() == epr_cap_c_, "typed caption field overwritten"
            # 2. Zeichnung am selben Pfad geaendert (Octet/ChemDraw speichert): Formel, Molmasse und Bilder folgen
            mol_c_(sp_c_, "OC(=O)c1ccccc1")
            assert wc_.chemdraw_saved(sp_c_) and wc_.compound["formula"] == "C7H6O2", wc_.compound
            settle_c_("C7H6O2")
            assert abs(wc_.series[gf_]["mw"] - 122.12) < 0.01 and wc_.ed_mw.text().startswith("122.1"), wc_.ed_mw.text()
            assert abs(wc_.series[go_]["mw"] - 122.12) < 0.01
            assert wc_.hrms_tab.formula()[0] == "C7H6O2" and "C₇H₆O₂" in wc_.irms_tab.lbl_ea_formula.text()
            for t_ in (wc_.fl_tab, wc_.irms_tab):                # Bild der Struktur: nicht das alte aus dem Cache
                assert t_.structure_asset(sp_c_)["formula"] == "C7H6O2", t_.structure_asset(sp_c_)["formula"]
            # 3. Rueckgaengig stellt die Angaben in allen Tabs wieder her
            wc_.undo()
            pump(0.8)
            assert wc_.compound["formula"] == "C6H6O" and wc_.series[gf_]["mw"] == 94.11 and wc_.ed_mw.text() == "94.11"
            assert wc_.hrms_tab.formula()[0] == "C6H6O" and "Q7" in wc_.nav_buttons[0].full_text
            # 4. von Hand eingetragene Molmasse gilt, bis die Verbindung geaendert wird: dann folgt die Serie wieder
            wc_.ed_mw.setText("130.5")
            wc_.mw_edited()
            assert wc_.series[gf_]["mw"] == 130.5
            wc_.set_compound({**wc_.compound, "mw": 99.0})
            pump(0.6)
            assert wc_.series[gf_]["mw"] == wc_.series[go_]["mw"] == 99.0 and wc_.ed_mw.text() == "99.00", wc_.series[gf_]["mw"]
