            assert (w.compound["name"], w.compound["formula"], list(w.groups)) == ("S3", "C16H16N2", ["S3"]), w.compound
            assert not [p_.name for p_ in (out / "demo").rglob("*") if re.search("selftest|test-|xtest|otest", p_.name.lower())]
            assert [e_["name"] for e_ in w.xray_state["entries"]] == ["S3"]
            assert sorted(a_["label"] for a_ in w.xray_tab.molecule(w.xray_tab.entry()).atoms if a_["el"] != "H") == \
                sorted([f"C{i_}" for i_ in range(1, 17)] + ["N1", "N2"])
            assert sum(e_ != "H" for e_ in w.dft_tab.geometry(w.dft_state["entries"][0])[1]) == 18
            st_file_ = PRJ.load(out / "demo")                  # gespeichert, nicht nur im Fenster (war leer: _restoring)
            assert st_file_.get("cv", {}).get("files") and st_file_.get("eps", {}).get("files"), sorted(st_file_)
            pump(0.4)                                         # Beispiel: Pfade zeigen auf die Kopien, nicht in den Temp-Ordner
