            assert [a_.text() for a_ in card_l.menu(k_l).actions()] == [T("lab_menu_edit"), T("lab_menu_hide"),
                                                                         T("lab_menu_reset")]
            assert not card_l.menu(k_l).actions()[2].isEnabled()           # nichts zurückzusetzen
