            def pdf_text_(tab_, name_):
                files_ = tab_.export_to(out / "labels_sec" / name_)
                return "".join(p_.get_text() for p_ in pymupdf.open(str(next(f_ for f_ in files_ if f_.suffix == ".pdf"))))
            (out / "labels_sec").mkdir(exist_ok=True)
