            assert [a_.text() for a_ in t_l.label_card.menu_empty(got_x[0]).actions()] == [T("lab_menu_add")]
            assert not t_l.label_card.btn_extra_off.isEnabled()
            w.activateWindow()                                           # Feld bekommt wirklich den Fokus
            pump(0.2)
