            was34_ = c34_.isChecked()
            QT34_.mouseClick(c34_, Qt.LeftButton, Qt.NoModifier, QP34_(3, c34_.height() // 2))
            assert c34_.isChecked() != was34_ and t34_.st["e12_each"] == c34_.isChecked()
            QT34_.mouseClick(c34_, Qt.LeftButton, Qt.NoModifier, QP34_(c34_.width() // 2, c34_.height() // 2))
            assert c34_.isChecked() == was34_
            assert c34_.toolTip()                                          # gekürzter Text: Langform im Tooltip
            f34_ = next(x_ for x_ in t34_.findChildren(QAbstractSpinBox)
                        if getattr(x_, "model", None) == (t34_.cb_stack, t34_.sp_gap))
            t34_.cb_stack.setChecked(False)                                # Schalter + Wert: ein Feld, unten „aus“
            gap34_ = t34_.sp_gap.value()
            assert f34_.text() == T("off") and t34_.cb_stack.isHidden() and t34_.sp_gap.isHidden()
            f34_.stepBy(1)                                                 # aus -> ein: der zuletzt benutzte Wert
            assert t34_.cb_stack.isChecked() and f34_.value() == gap34_ and t34_.st["stack"]
            f34_.setValue(2.5)
            assert t34_.sp_gap.value() == 2.5 and t34_.st["stack_gap"] == 2.5
            f34_.setValue(f34_.minimum())
            assert not t34_.cb_stack.isChecked() and f34_.text() == T("off") and t34_.sp_gap.value() == 2.5
            t34_.cb_stack.blockSignals(True)                               # Zustand laden (Signale blockiert): Feld folgt
            t34_.cb_stack.setChecked(True)
            t34_.cb_stack.blockSignals(False)
