            assert abs(y35_ - (tb35_.tabRect(0).top() + 3)) <= 1 and t35_.kpi_box.labels[0].height() == 26, y35_
            t35_.right_tabs.setCurrentWidget(t35_.si_page)                 # SI-Text: Unterschrift mit Feldern + Methodentext
            pump(0.3)
