            assert t35_.si_page.isAncestorOf(t35_.ed_cap["conc"]) and t35_.si_page.isAncestorOf(t35_.lbl_cap)
            assert not t35_.column_fit.content.isAncestorOf(t35_.grp_caption), "Bildunterschrift nicht mehr links"
            assert "S3" in t35_.lbl_cap.text() and t35_.lbl_methods.text() == t35_.methods_text() != ""
            t35_.copy_caption()
