        with section:                                        # DFT, Stil IboView: Stäbe frei, Symbole abschaltbar, Knöpfe passen
            w.open_project(out / "demo_pub_items" / "S3", recent=False)
            pump(0.4)
            t26_ = w.dft_tab
            t26_.load_xyz(str(xyzf_))
            t26_.cmb_style.setCurrentIndex(t26_.cmb_style.findData("iboview"))
            t26_.cb_lab.setChecked(True)
            t26_.render()
            f26_ = t26_.F
            assert f26_.elem_lab and f26_.rod_pairs and not t26_.cb_orb_lab.isHidden()
            tr26_ = f26_.ax.transData
            rend26_ = f26_.fig.canvas.get_renderer()
