                for on_t8 in (False, True):
                    x_t.pack(e_t8)["on"] = on_t8
                    x_t.render(push=False)
                    x_t.show_pack()
                    assert x_t._pack_rows and bool(x_t.lbl_pack_off.text()) != on_t8, (on_t8, x_t.lbl_pack_off.text())
                x_t.pack(e_t8)["on"] = False
                x_t.render(push=False)
