            def pump_m2(sec=0.2):
                t0_ = time.time()
                while time.time() - t0_ < sec:
                    QApplication.processEvents()
                    QApplication.sendPostedEvents(None, QEvent.DeferredDelete)   # ersetzte Oberfläche wirklich löschen
