            g69_n2 = next(g_ for g_ in t_n2.ana(t_n2.current())["signals"] if g_["lo"] < 6.93 < g_["hi"])
            t_n2._sel_uid = g69_n2["uid"]
            t_n2.fill_ana()
            t_n2.ed_cls.setText("dd")
