        with section:
            # Entscheidung 113: 13C-Vorschlag nur bei bestätigter Phase gefiltert (höchstes Maximum in ±1 Hz), Rest genannt
            from elucida.core import nmr_analysis as NA_pk
            from elucida.formats import bruker_nmr as BN_pk
            y_pk = np.zeros(200)
