                for p_bd in (e_bd / "acqus", e_bd / "pdata", e_bd / "pdata" / "1", e_bd / "pdata" / "1" / "1r"):
                    w.dropEvent(Drop_bd([p_bd]))                         # dasselbe Experiment: nichts doppelt
